void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  uint h = uint(fragCoord.x) * 1597334677u ^ uint(fragCoord.y) * 3812015801u;
  h = (h ^ (h >> 16)) * 2246822519u;
  float bruit = float(h >> 9) / 8388608.0;
  mat2 m = mat2(1.0, 0.5, -0.5, 1.0);
  vec2 q = inverse(m) * (uv - 0.5);
  float v = round(q.x * 5.0) / 5.0 + trunc(q.y * 4.0) / 4.0 + inversesqrt(1.0 + q.x * q.x) * 0.2;
  fragColor = vec4(vec3(bruit * 0.3 + 0.5 * v + 0.3), 1.0) * vec4(1.0, 0.8 + 0.2 * float(int(h & 1u)), 0.9, 1.0);
}
